Matching Ayahs
- = Alif, Lam, Mim. 2:1; 3:1; 29:1; 30:1; 31:1; 32:1
- = Sila ang nasa tamang patnubay mula sa kanilang Panginoon, at sila ang matagumpay. 2:5; 31:5
- = O mga anak ni Israel, alalahanin ninyo ang Aking biyaya na ipinagkaloob Ko sa inyo at na ginawa Ko kayong higit sa lahat ng mga nilalang (mga tao). 2:47; 2:122
- = Iyon ay isang pamayanang lumipas na. Makakamit nito ang kinita nito, at makakamit ninyo ang kinita ninyo. At kayo ay hindi tatanungin tungkol sa kanilang ginagawa. 2:134; 2:141
- = Mananatili sila roon magpakailanman; ang pagdurusa ay hindi pagagaanin para sa kanila, at hindi sila bibigyan ng palugit. 2:162; 3:88
- = Maliban sa mga nagbabago ng isip pagkatapos niyan at nagtutuwid. Sapagkat tunay na ang Allah ay Mapagpatawad, Mapagmahal. 3:89; 24:5
- = Ngunit ang mga hindi sumampalataya at itinanggi ang Aming mga tanda – sila ang mga kasama ng Impiyerno. 5:10; 5:86
- = At walang tanda mula sa mga tanda ng kanilang Panginoon ang dumarating sa kanila, maliban na sila ay tumatalikod dito. 6:4; 36:46
- = At tunay na ginawan ng biro ang mga sugo bago ka pa man, ngunit ang mga nang-uyam sa kanila ay binalot ng kanilang ginawan ng biro. 6:10; 21:41
- = Sabihin mo: "Tunay na ako ay natatakot, kung ako ay sumuway sa aking Panginoon, sa pagdurusa ng isang Dakilang Araw." 6:15; 39:13
- = Kaya ang lindol ay sumakmal sa kanila, at sila ay naging mga patay na nakabuwal sa kanilang mga tahanan. 7:78; 7:91
- = Kaya inihagis niya ang kanyang tungkod, at narito, ito ay naging isang malinaw na ahas. 7:107; 26:32
- = At inilabas niya ang kanyang kamay, at narito, ito ay naging puti (kumikinang) para sa mga tumitingin. 7:108; 26:33
- = Sila ay nagsabi: "Kami ay sumampalataya sa Panginoon ng mga nilalang." 7:121; 26:47
- = Ang Panginoon ni Moises at Aaron. 7:122; 26:48
- = At Ako ay magbibigay sa kanila ng palugit. Tunay, ang Aking plano ay matatag. 7:183; 68:45
- = Siya ang nagpadala ng Kanyang Sugo na may patnubay at relihiyon ng katotohanan, upang gawin itong nangingibabaw sa lahat ng relihiyon, kahit na ayaw ng mga tagapagtambal. 9:33; 61:9
- = O Propeta, makipaglaban ka sa mga hindi sumasampalataya at sa mga mapagkunwari, at maging matigas ka sa kanila. Ang kanilang kanlungan ay Impiyerno, at napakasamang hantungan! 9:73; 66:9
- = At sila ay nagsasabi: "Kailan ang pangakong ito, kung kayo ay mga tapat?" 10:48; 21:38; 27:71; 34:29; 36:48; 67:25
- = At tunay na isinugo Namin si Moises na may Aming mga tanda at isang malinaw na awtoridad. 11:96; 40:23
- = At tunay na ibinigay Namin kay Moises ang Kasulatan, ngunit pinagtatalunan ito. At kung hindi dahil sa isang salita na nauna mula sa iyong Panginoon, ito sana ay napagpasiyahan na sa pagitan nila. At tunay na sila ay may pag-aalinlangan tungkol dito. 11:110; 41:45
- = Iyan ay hindi mahirap para sa Allah. 14:20; 35:17
- = "At kapag aking nahubog siya at hiningahan siya ng Aking Espiritu, kayo ay magpatirapa sa kanya." 15:29; 38:72
- = Kaya ang mga anghel ay nagpatirapa – lahat sila. 15:30; 38:73
- = (Allah) ay nagsabi: "Kaya lumabas ka mula rito, sapagkat tunay na ikaw ay itinaboy." 15:34; 38:77
- = (Iblis) ay nagsabi: "Panginoon ko, kaya bigyan Mo ako ng palugit hanggang sa Araw na sila ay muling bubuhayin." 15:36; 38:79
- = (Allah) ay nagsabi: "Kaya tunay na ikaw ay kabilang sa mga binigyan ng palugit." 15:37; 38:80
- = Hanggang sa Araw ng takdang panahon." 15:38; 38:81
- = Maliban sa Iyong mga piling lingkod sa kanila. 15:40; 38:83
- = Tunay na ang mga matutuwid ay nasa mga halamanan at mga bukal. 15:45; 51:15
- = Siya ay nagsabi: "Kaya ano ang inyong tungkulin, O mga sugo?" 15:57; 51:31
- = Sila ay nagsabi: "Tunay na kami ay isinugo sa isang taong makasalanan." 15:58; 51:32
- = Ang mga sumampalataya at hindi hinahalo ang kanilang pananampalataya sa kawalang-katarungan – sila ang may kapanatagan, at sila ay mga matuwid na pinapatnubayan. 16:42; 29:59
- = Upang kanilang itanggi ang Aming ipinagkaloob sa kanila. Kaya magsaya kayo, sapagkat malalaman ninyo. 16:55; 30:34
- = Pagkatapos ay sumunod siya sa isang daan. 18:89; 18:92
- = Pumunta ka kay Paraon. Tunay na siya ay lumabag. 20:24; 79:17
- = At sila na nag-iingat ng kanilang pribadong bahagi. 23:5; 70:29
- = Maliban sa kanilang mga asawa o sa mga nasa kanilang kanang kamay – sapagkat tunay na sila ay hindi dapat sisihin. 23:6; 70:30
- = Ngunit ang sinumang maghanap ng higit pa doon, sila ay mga lumalabag. 23:7; 70:31
- = At sila na nag-iingat sa kanilang mga ipinagkatiwala at mga pangako. 23:8; 70:32
- = Siya ay nagsabi: "Panginoon ko, tulungan Mo ako sapagkat itinanggi nila ako." 23:26; 23:39
- = Ta, Sin, Mim. 26:1; 28:1
- = Ito ang mga talata ng malinaw na Aklat. 26:2; 28:2
- = Tunay na sa mga ito ay may tanda, ngunit ang karamihan sa kanila ay hindi sumasampalataya. 26:8; 26:67; 26:103; 26:121; 26:174; 26:190
- = At tunay na ang iyong Panginoon – Siya ang Makapangyarihan, ang Mapagmahal. 26:9; 26:68; 26:104; 26:122; 26:140; 26:159; 26:175; 26:191
