- Ang masasamang bunga ng kanilang ginawa ay tumama sa kanila, at ang kanilang kinukutya ay pumalibot sa kanila. (سَيِّئَاتُ مَا عَمِلُوا وَحَاقَ بِهِم مَّا كَانُوا بِهِ يَسْتَهْزِئُونَ) 16:34; 45:33
